-- Canonical AOJ indices also cover databases that imported only part of a contest.
ON CONFLICT (task_id) DO UPDATE
SET task_table_index = EXCLUDED.task_table_index,
    updated_at = CURRENT_TIMESTAMP
WHERE task.contest_type = 'AOJ_PCK'
  AND task.contest_id = EXCLUDED.contest_id
  AND task.task_table_index IS DISTINCT FROM EXCLUDED.task_table_index;
